CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, companyId INTEGER NOT NULL, code TEXT NOT NULL, legalName TEXT NOT NULL, currencyCode TEXT NOT NULL DEFAULT 'SAR', status TEXT NOT NULL DEFAULT 'ACTIVE', UNIQUE(companyId, code));
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY AUTOINCREMENT, companyId INTEGER NOT NULL, code TEXT NOT NULL, legalName TEXT NOT NULL, currencyCode TEXT NOT NULL DEFAULT 'SAR', status TEXT NOT NULL DEFAULT 'ACTIVE', UNIQUE(companyId, code));
CREATE TABLE IF NOT EXISTS invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, docNo TEXT NOT NULL UNIQUE, customerId INTEGER NOT NULL, warehouseId INTEGER NOT NULL, currencyCode TEXT NOT NULL DEFAULT 'SAR', subtotal TEXT NOT NULL DEFAULT '0', taxTotal TEXT NOT NULL DEFAULT '0', grandTotal TEXT NOT NULL DEFAULT '0', status TEXT NOT NULL DEFAULT 'DRAFT', idempotencyKey TEXT NOT NULL UNIQUE, sourceForm TEXT NOT NULL DEFAULT 'ARST004', createdBy TEXT NOT NULL DEFAULT 'workbench.user', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, postedAt TEXT);
CREATE TABLE IF NOT EXISTS invoice_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, invoiceId INTEGER NOT NULL, itemId INTEGER NOT NULL, quantity TEXT NOT NULL, unitPrice TEXT NOT NULL, taxAmount TEXT NOT NULL DEFAULT '0', lineTotal TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, itemId INTEGER NOT NULL, warehouseId INTEGER NOT NULL, sourceInvoiceId INTEGER, movementType TEXT NOT NULL, quantityIn TEXT NOT NULL DEFAULT '0', quantityOut TEXT NOT NULL DEFAULT '0', unitCost TEXT NOT NULL DEFAULT '0', totalCost TEXT NOT NULL DEFAULT '0', balanceAfter TEXT NOT NULL DEFAULT '0', createdBy TEXT NOT NULL, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS journal_entry_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, journalEntryId INTEGER NOT NULL, accountCode TEXT NOT NULL, accountName TEXT, description TEXT, debit TEXT NOT NULL DEFAULT '0', credit TEXT NOT NULL DEFAULT '0');
